(1648, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'Le mal de Pott est une affection :', '[{"l":"A","t":"caractérisée par une dissémination en règle par voie hématogène","c":true},{"l":"B","t":"la plus rare des formes de tuberculose ostéoarticulaire","c":false},{"l":"C","t":"à évolution cyclique en trois phases","c":true},{"l":"D","t":"la négativité de l’intradermoréaction à la tuberculine élimine le diagnostic","c":false},{"l":"E","t":"la chirurgie est souvent indiquée avant le début du traitement médical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1649, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'La spondylite tuberculeuse : (cochez les propositions correctes)', '[{"l":"A","t":"Est l’infection tuberculeuse du corps et du disque intervertébral","c":false},{"l":"B","t":"Est une infection tuberculeuse pauci bacillaire","c":true},{"l":"C","t":"Son diagnostic peut être écarté devant une radiographie normale du rachis","c":false},{"l":"D","t":"Elle ne touche pas le rachis cervical","c":false},{"l":"E","t":"Elle peut se manifester par des douleurs rachidiennes mécaniques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1650, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'L’agent pathogène est :', '[{"l":"A","t":"Le staphylocoque doré","c":false},{"l":"B","t":"Le streptocoque","c":false},{"l":"C","t":"Le bacille de Koch","c":true},{"l":"D","t":"Le pseudomonas aeruginosa","c":false},{"l":"E","t":"L’Escherichia coli","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1651, 22, 'Chirurgie pédiatrique', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'La tuberculose ostéoarticulaire est une infection de :', '[{"l":"A","t":"L’articulation","c":false},{"l":"B","t":"L’os","c":false},{"l":"C","t":"Le muscle","c":false},{"l":"D","t":"Le tendon","c":false},{"l":"E","t":"L’os et l’articulation","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
