(1653, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'La tuberculose ostéoarticulaire est une maladie :', '[{"l":"A","t":"Rare","c":false},{"l":"B","t":"Endémique","c":false},{"l":"C","t":"Qui est en augmentation dans les pays en voie de développement","c":true},{"l":"D","t":"Qui est en diminution dans le monde","c":false},{"l":"E","t":"Qui a disparu","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
