(1655, 27, 'Rhumatologie', 'Non classé', NULL, false, true, 'La maladie de Lyme est une maladie qui peut donner un rhumatisme post-infectieux. Elle est due à :', '[{"l":"A","t":"Un virus","c":false},{"l":"B","t":"Une bactérie","c":true},{"l":"C","t":"Un champignon","c":false},{"l":"D","t":"Un parasite","c":false},{"l":"E","t":"Une allergie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1656, 5, 'Chirurgie pédiatrique', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'L’agent pathogène le plus fréquent est :', '[{"l":"A","t":"Le streptocoque","c":false},{"l":"B","t":"Le staphylocoque doré","c":true},{"l":"C","t":"Le pneumocoque","c":false},{"l":"D","t":"L’Escherichia coli","c":false},{"l":"E","t":"Le pseudomonas aeruginosa","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1657, 11, 'Rhumatologie', 'Boiterie chez l’enfant', NULL, false, true, 'Les signes cliniques d’une tuberculose ostéoarticulaire sont :', '[{"l":"A","t":"Une douleur, un œdème, une rougeur","c":false},{"l":"B","t":"Une douleur chronique, une raideur articulaire, une boiterie","c":true},{"l":"C","t":"Une douleur aiguë, une fièvre","c":false},{"l":"D","t":"Une douleur, un œdème, une fièvre","c":false},{"l":"E","t":"Une douleur, une déformation, une crépitation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1658, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'Le traitement de la tuberculose ostéoarticulaire est :', '[{"l":"A","t":"La chirurgie","c":false},{"l":"B","t":"Le traitement médical","c":true},{"l":"C","t":"La kinésithérapie","c":false},{"l":"D","t":"L''immobilisation","c":false},{"l":"E","t":"La traction continue","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
