(1660, 22, 'Rhumatologie', 'Mal de Pott et tuberculose ostéo-articulaire', NULL, false, true, 'Le diagnostic d’une tuberculose ostéoarticulaire est souvent :', '[{"l":"A","t":"Précoce","c":false},{"l":"B","t":"Tardif","c":true},{"l":"C","t":"Immédiat","c":false},{"l":"D","t":"Difficile","c":false},{"l":"E","t":"Impossible","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1661, 4, 'MPR', 'Situations d’handicap et concept de qualité de vie', NULL, false, true, 'Les situation de handicap et concept de qualité 1. Parmi les étiologies du handicap, un seul n’est pas correct lequel ?', '[{"l":"A","t":"Les lésions cérébrales","c":false},{"l":"B","t":"Les lésions médullaires","c":false},{"l":"C","t":"Les rhumatismes inflammatoires","c":false},{"l":"D","t":"Les lésions du plexus brachial","c":false},{"l":"E","t":"Le syndrome grippal","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1662, 4, 'MPR', 'Situations d’handicap et concept de qualité de vie', NULL, false, true, 'Le Handicap : cochez la ou les R juste(s)', '[{"l":"A","t":"Dans 80 % des cas, le handicap n’est pas visible au premier regard.","c":true},{"l":"B","t":"Dans les pays en voie de développement, ce sont les pathologies infectieuses et infantiles qui sont les principales causes de handicap.","c":true},{"l":"C","t":"Dans les pays développés, ce sont des pathologies dues au vieillissement, en particulier les pathologies cardio-neuro-vasculaires, qui sont le plus souvent à l’origine d’une situation de handicap","c":true},{"l":"D","t":"Dans les pays développés, ce sont les pathologies infectieuses et infantiles qui sont les principales causes de handicap.","c":false},{"l":"E","t":"Dans les pays en voie de développement, ce sont des pathologies dues au vieillissement, en particulier les pathologies cardio-neuro-vasculaires, qui sont le plus souvent à l’origine d’une situation de handicap","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1663, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Ia paraplégie :(cochez la réponse juste)', '[{"l":"A","t":"est une perte de la motricité sans perte de la sensibilité dans les territoires situés au-dessous de la lésion médullaire","c":false},{"l":"B","t":"se définie comme la perte de la motricité volontaire et de la sensibilité dans les territoires situés au-dessous de la lésion médullaire","c":true},{"l":"C","t":"les troubles sphinctériens ne sont jamais présents","c":false},{"l":"D","t":"elles guérissent toujours au bout de quelques jours d’hospitalisation","c":false},{"l":"E","t":"elle est toujours d’origine traumatique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1664, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'Concernant les principes de base en Médecine Physique et Réadaptation (MPR) : Quelle(s) est (sont) la (les) proposition(s) juste(s)?', '[{"l":"A","t":"Établir les critères pronostiques de récupération ne relève pas des compétences d’un médecin MPR.","c":false},{"l":"B","t":"Tout acte de rééducation auprès d’un patient se fait en lien avec le médecin MPR prescripteur.","c":true},{"l":"C","t":"Un kinésithérapeute peut réaliser des actes de masso-kinésithérapie sans prescription médicale.","c":false},{"l":"D","t":"Les ergothérapeutes peuvent réaliser de petit appareillage (orthèses de posture ou de fonction).","c":true},{"l":"E","t":"Les troubles de la déglutition sont souvent pris en charge par l’orthophoniste.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1665, 24, 'Traumatologie', 'Traumatismes vertébraux-médullaires', NULL, false, true, 'Madame F.Z, âgée de 40 ans, est mariée, a trois enfants, est femme de ménage et habite au 4ème étage sans ascenseur. Madame F.Z présente une paraplégie post traumatique de niveau D12 classée ASIA A. À 6 mois postopératoires, elle garde le même tableau clinique. Quelle(s) est (sont) la (les) proposition(s) juste(s) ?', '[{"l":"A","t":"Madame F.Z est totalement dépendante dans les activités de vie quotidienne (soins de l’apparence, alimentation, toilette, habillage).","c":false},{"l":"B","t":"La marche est possible avec orthèses de type releveurs et cannes.","c":false},{"l":"C","t":"Le contrôle vésico sphinctérien est impossible.","c":true},{"l":"D","t":"L’habitat au 4ème étage sans ascenseur constitue un facteur environnemental limitant pour cette patiente.","c":true},{"l":"E","t":"Madame F.Z peut reprendre son travail antérieur.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1666, 18, 'MPR', 'Amputations des membres', NULL, false, true, 'Concernant l’appareillage orthopédique externe, quelle(s) est (sont) parmi les propositions suivantes celle(s) qu’est (sont) exacte(s) ?', '[{"l":"A","t":"Une orthèse est un dispositif médical externe non pharmacologique appliqué à un membre/rachis.","c":true},{"l":"B","t":"L’orthèse remplace un membre ou un segment de membre manquant.","c":false},{"l":"C","t":"Le corset Lyonnais est une orthèse du tronc réalisée sur mesure par un orthoprothésiste.","c":true},{"l":"D","t":"La prothèse fémorale est prescrite sur ordonnance de grand appareillage par un médecin spécialiste (MPR, chirurgien orthopédiste).","c":true},{"l":"E","t":"Les pieds prothétiques ont les mêmes propriétés mécaniques.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1667, 18, 'MPR', 'Amputations des membres', NULL, false, true, 'Parmi les propositions suivantes concernant les amputations des membres, laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"Les amputations du membre inférieur sont, dans la grande majorité des cas, d’origine vasculaire.","c":true},{"l":"B","t":"Les amputations majeures au membre inférieur sont des amputations qui ne conservent pas l’appui distal.","c":true},{"l":"C","t":"À l’étage tibial, le niveau idéal de section osseuse, en termes d’appareillage, se situe au tiers inférieur.","c":false},{"l":"D","t":"Le capitonnage musculaire du moignon fait appel aux techniques de myoplasties et myodèses.","c":true},{"l":"E","t":"La prothèse pour amputation transformorale comporte : une emboîture, un manchon intermédiaire, une pièce de liaison et d’un effecteur terminal (le pied prothétique).","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1668, 18, 'MPR', 'Amputations des membres', NULL, false, true, 'La cause la plus fréquente d''une amputation est :', '[{"l":"A","t":"Un traumatisme","c":false},{"l":"B","t":"Une infection","c":false},{"l":"C","t":"Une maladie vasculaire (diabète)","c":true},{"l":"D","t":"Une tumeur","c":false},{"l":"E","t":"Une maladie neurologique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1669, 2, 'MPR', 'Polyarthrite rhumatoïde', NULL, false, true, 'Les “escarres” sont une complication de :', '[{"l":"A","t":"La paraplégie et la tétraplégie","c":true},{"l":"B","t":"L’arthrose","c":false},{"l":"C","t":"La polyarthrite rhumatoïde","c":false},{"l":"D","t":"La spondylarthrite","c":false},{"l":"E","t":"La goutte","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1670, 3, 'MPR', 'Principe de base en médecine physique et réadaptation', NULL, false, true, 'L’appareillage est une partie de la MPR qui a pour but de :', '[{"l":"A","t":"Rétablir la mobilité","c":false},{"l":"B","t":"Rétablir la fonction","c":true},{"l":"C","t":"Rétablir la force","c":false},{"l":"D","t":"Rétablir l’anatomie","c":false},{"l":"E","t":"Rétablir l’autonomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
