(1686, 7, 'Chirurgie pédiatrique', 'Complication de l’immobilité et décubitus', NULL, false, true, 'L’infection urinaire est une complication :', '[{"l":"A","t":"Immédiate","c":false},{"l":"B","t":"Précoce","c":false},{"l":"C","t":"Tardive","c":true},{"l":"D","t":"Liée à une luxation","c":false},{"l":"E","t":"Liée à une mauvaise réduction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1687, 17, 'Traumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'Luxation congénitale de la hanche 1. L’examen clinique de la hanche chez un nouveau-né est :', '[{"l":"A","t":"Obligatoire à la naissance","c":true},{"l":"B","t":"Obligatoire uniquement si le nouveau-né présente des facteurs de risque favorisant une luxation de la hanche","c":false},{"l":"C","t":"Est un examen de dépistage courant","c":true},{"l":"D","t":"Doit être fait par un pédiatre","c":false},{"l":"E","t":"Toute asymétrie est suspecte et doit approfondir les explorations","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1688, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Dans l’examen de dépistage d’une LCH, le signe de Galeazzi est :', '[{"l":"A","t":"Une asymétrie des plis inguinaux","c":false},{"l":"B","t":"Une asymétrie des plis fessiers","c":false},{"l":"C","t":"Une asymétrie des plis poplités","c":false},{"l":"D","t":"Un raccourcissement de la cuisse","c":true},{"l":"E","t":"Une limitation de l’abduction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1689, 11, 'Chirurgie pédiatrique', 'Boiterie chez l’enfant', NULL, false, true, 'Boiterie d’équilibration se définit par : (cochez la ou les réponses justes) :', '[{"l":"A","t":"Diminution du temps d’appui du membre atteint.","c":false},{"l":"B","t":"Bascule du tronc et épaules du côté du membre pathologique par instabilité de la hanche.","c":true},{"l":"C","t":"Altération des éléments fondamentaux du pas.","c":true},{"l":"D","t":"Diminution de la longueur du pas.","c":true},{"l":"E","t":"Boiterie d’épaule","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1690, 14, 'Autre', 'Malformations congénitales du pied chez l’enfant', NULL, false, true, 'Les déformations congénitales :', '[{"l":"A","t":"Surviennent au cours de la vie fœtale","c":false},{"l":"B","t":"Surviennent au cours de la vie embryonnaire","c":true},{"l":"C","t":"Sont secondaires à un trouble de l’organogenèse","c":true},{"l":"D","t":"Nécessitent une prise en charge le plus souvent urgente","c":false},{"l":"E","t":"Toutes les réponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1691, 18, 'MPR', 'Amputations des membres', NULL, false, true, 'Séquelles de l’amputation 1 L’amputation : cochez la ou les R juste(s)', '[{"l":"A","t":"L’ostéomyoplastie est la technique chirurgicale de choix.","c":true},{"l":"B","t":"Le nombre d’amputations de membre supérieur représenterait environ 10 à 15% des amputations de membres inférieurs.","c":true},{"l":"C","t":"Les amputations des membres supérieurs sont plus fréquentes que les amputations des membres inférieurs","c":false},{"l":"D","t":"Les amputations de causes vasculaires touchent surtout les sujets jeunes, rarement les personnes âgées","c":false},{"l":"E","t":"Les amputations de causes tumorales sont consécutives à des tumeurs des os et des parties molles.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1692, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'à propos de la luxation du coude (cochez la réponse fausse)', '[{"l":"A","t":"peut se compliquer d’un syndrome des loges","c":false},{"l":"B","t":"la réduction doit être effectuée sous anesthesie et le plus rapidement possible","c":false},{"l":"C","t":"elle est traitée le plus souvent chirurgicalement","c":true},{"l":"D","t":"est une rupture des ligaments lateraux du coude","c":false},{"l":"E","t":"son diagnostic est clinique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
