(1694, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Concernant les luxations du coude, la forme anatomopathologique la plus fréquente est : (cochez la réponse juste)', '[{"l":"A","t":"La luxation antérieure.","c":false},{"l":"B","t":"La luxation postérieure pure.","c":false},{"l":"C","t":"La luxation postéro-latérale.","c":true},{"l":"D","t":"La luxation latérale.","c":false},{"l":"E","t":"Luxation de l’olécrane isolée.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
