(1698, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', NULL, false, true, 'Le traitement de la raideur du coude après une luxation peut nécessiter :', '[{"l":"A","t":"Une immobilisation prolongée","c":false},{"l":"B","t":"De la kinésithérapie","c":true},{"l":"C","t":"Une nouvelle réduction","c":false},{"l":"D","t":"Une chirurgie","c":false},{"l":"E","t":"Un plâtre","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1699, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Le diagnostic est confirmé par une radiographie du coude de face et :', '[{"l":"A","t":"De profil","c":true},{"l":"B","t":"De trois-quarts","c":false},{"l":"C","t":"De profil avec le poignet en supination","c":false},{"l":"D","t":"De face en supination","c":false},{"l":"E","t":"De face en pronation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
