(1701, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'La luxation traumatique du coude est la deuxième luxation la plus fréquente après celle de l’épaule. Elle est le plus souvent :', '[{"l":"A","t":"Antérieure","c":false},{"l":"B","t":"Postérieure","c":true},{"l":"C","t":"Médiale","c":false},{"l":"D","t":"Latérale","c":false},{"l":"E","t":"Inférieure","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1702, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Le traitement d’une luxation du coude est d’abord :', '[{"l":"A","t":"Chirurgical","c":false},{"l":"B","t":"L’immobilisation","c":false},{"l":"C","t":"La réduction de la luxation","c":true},{"l":"D","t":"La pose d’une attelle","c":false},{"l":"E","t":"La prise d’antalgiques","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
