(1707, 41, 'Traumatologie', 'Luxation du coude', NULL, false, true, 'Un patient avec une luxation du coude présente :', '[{"l":"A","t":"Une mobilité normale","c":false},{"l":"B","t":"Une impotence fonctionnelle relative","c":false},{"l":"C","t":"Une impotence fonctionnelle absolue","c":true},{"l":"D","t":"Une absence de douleur","c":false},{"l":"E","t":"Une déformation en valgus","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
