(1710, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, false, true, 'Concernant la fracture supra-condylienne du coude chez l’enfant, laquelle de ces affirmations est correcte ?', '[{"l":"A","t":"Est une urgence thérapeutique","c":true},{"l":"B","t":"Expose au risque de syndrome de Volkmann","c":true},{"l":"C","t":"Le déplacement se fait le plus souvent en extension","c":false},{"l":"D","t":"Le trait de fracture est intra-articulaire","c":false},{"l":"E","t":"La classification de Gartland guide le traitement","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1711, 25, 'Traumatologie', 'Fracture diaphysaire des deux os de l’avant-bras', NULL, false, true, 'pour une fracture de la tête radiale (cochez la réponse juste):', '[{"l":"A","t":"non déplacée, le traitement n’est que chirurgicale","c":false},{"l":"B","t":"la resection de la tête radiale n’entraine aucune instabilité du coude","c":false},{"l":"C","t":"si elle est associée à une disjonction radio-uhnaire inférieur et une rupture de la membrane interosseuse constitue le syndrome d’essex lopresti","c":true},{"l":"D","t":"après une fracture complexe traitée orthopediquement, la raideur du coude est rare","c":false},{"l":"E","t":"la pronosupination est toujours conservée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1712, 32, 'Traumatologie', 'Fracture de l’humérus', NULL, false, true, 'La fracture condylienne externe de la palette humérale comprend :', '[{"l":"A","t":"l’épitrochlée + le capitellum + joue externe de la trochlée","c":true},{"l":"B","t":"l’épicondyle + le capitellum + joue interne de la trochlée","c":false},{"l":"C","t":"l’épicondyle + l’épitrochlée + joue interne de la trochlée","c":false},{"l":"D","t":"l’épitrochlée + le capitellum + joue externe de la trochlée","c":false},{"l":"E","t":"aucune réponse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1713, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Lors de la mise en place des attelles postérieures au membre supérieur, la bande Velpeau doit passer en plein milieu du coude de façon centrée pour :', '[{"l":"A","t":"Éviter toute pronation ou supination","c":false},{"l":"B","t":"Protéger la saillie osseuse de l’olécrane","c":true},{"l":"C","t":"Maintenir le pouce au zénith","c":false},{"l":"D","t":"Éviter une compression d’un axe vasculaire","c":false},{"l":"E","t":"Protéger la peau du coude qui est fragile","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
