(1715, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture de la tête radiale est une fracture de :', '[{"l":"A","t":"L’extrémité supérieure du radius","c":true},{"l":"B","t":"L’extrémité inférieure du radius","c":false},{"l":"C","t":"La diaphyse du radius","c":false},{"l":"D","t":"L’olécrâne","c":false},{"l":"E","t":"L’épicondyle","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
