(1729, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Parmi ces facteurs parentaux, lequel n’est PAS un facteur de risque de luxation congénitale de la hanche (LCH) ?', '[{"l":"A","t":"hérédité","c":false},{"l":"B","t":"accouchement par césarienne","c":false},{"l":"C","t":"présentation en siège","c":false},{"l":"D","t":"primiparité maternelle","c":false},{"l":"E","t":"prématurité (c’est un facteur protecteur)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
