(1731, 37, 'Traumatologie', 'Traumatismes osseux du genou', NULL, false, true, 'Un traumatisme par mécanisme du « tableau de bord » peut entraîner :', '[{"l":"A","t":"une luxation antérieure de la hanche","c":false},{"l":"B","t":"une fracture du poignet","c":false},{"l":"C","t":"une fracture de la rotule","c":true},{"l":"D","t":"une fracture-luxation postérieure de la hanche","c":true},{"l":"E","t":"une lésion ligamentaire du genou","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1732, 17, 'Traumatologie', 'Maladies luxantes de la hanche', NULL, false, true, 'Sur une radiographie du bassin de face, le U radiologique : (cochez la ou les réponses justes)', '[{"l":"A","t":"Est ouvert et peu dense quand la tête fémorale a peu habité la cotyle","c":true},{"l":"B","t":"La branche interne représente l''arrière fond du cotyle","c":false},{"l":"C","t":"Sa densité est plus intense en cas de luxation congénitale de la hanche","c":false},{"l":"D","t":"La lame quadrilatère de l''os coxal en constitue une partie","c":true},{"l":"E","t":"S''il est ouvert, il est le témoin d''une dysplasie acétabulaire","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
(1733, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', NULL, false, true, 'Sur une radiographie du bassin, en cas de présence d’un noyau épiphysaire à droite et en cas d’absence de noyau épiphysaire à gauche, quelle construction faire pour diagnostiquer une LCH (cochez la réponse juste)', '[{"l":"A","t":"OMBREDANE en bilateral","c":false},{"l":"B","t":"PUTTI en bilatéral","c":false},{"l":"C","t":"OMBREDANE à droite, PUTTI à gauche","c":true},{"l":"D","t":"OMBREDANE à gauche, PUTTI à droite","c":false},{"l":"E","t":"On ne peut pas interpréter la radiographie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR (Aw.Bk)"]'::jsonb),
